"""Game-over (Siege Casualty) screen from your art: the framed parchment, the red buttons and the XP bar.
The words and numbers are drawn on top each run."""
import base64
import io
import pygame

PNG = {
  'go_panel': '',
  'go_btn': '',
  'go_btn_down': '',
  'go_bar': '',
  'go_fill': '',
}
PANEL_W, PANEL_H = 948, 560
BTN_W, BTN_H = 300, 47
BAR_W, BAR_H = 400, 36
TRACK = (30, 9, 341, 18)          # where the fill goes inside the bar (x, y, w, h)
_C = {}


def img(name):
  s = _C.get(name)
  if s is None:
    s = pygame.image.load(io.BytesIO(base64.b64decode(PNG[name])))
    try:
      s = s.convert_alpha()
    except Exception:
      pass
    _C[name] = s
  return s


def ok():
  try:
    img('go_panel')
    return True
  except Exception:
    return False
